-- Carga inicial do Provider Catalog (spec-provider-catalog.md, ADR 0001).
-- Insere ou atualiza os 13 Providers sem trocar os ids: num banco que já os tem (gravados pelo Poll antigo),
-- os Incidents e as leituras continuam ligados a eles.
ON CONFLICT (`id`) DO UPDATE SET
    `name` = excluded.`name`,
    `url` = excluded.`url`,
    `status_page_url` = excluded.`status_page_url`,
    `type` = excluded.`type`,
    `logo` = excluded.`logo`,
    `is_major` = excluded.`is_major`,
    `active` = excluded.`active`,
    `display_order` = excluded.`display_order`;
